          {hasName && (
            <div id={nameId} {...stylex.props(styles.name)}>
              {name}
            </div>
          )}

          <div
            {...stylex.props(
              styles.childrenWrap,
              childrenAlignment,
              childrenGap,
            )}>
            {children}
          </div>

          {hasMetadata && (
            <div {...stylex.props(styles.metadata)}>{metadata}</div>
          )}
        </div>
      </article>
    </ChatMessageContext>
  );
