  },
  headerReducedGap: {
    marginBlockEnd: `calc(-1 * ${spacingVars['--spacing-1-5']})`,
  },
  nameRow: {
    height: spacingVars['--spacing-5'],
    display: 'flex',
    alignItems: 'center',
