  radiusVars,
  durationVars,
  easeVars,
  focusVars,
} from '@astryxdesign/core/theme/tokens.stylex';
import {getKey, mergeProps} from '@astryxdesign/core/utils';
import {Badge} from '@astryxdesign/core/Badge';
import {Icon, type IconName} from '@astryxdesign/core/Icon';
import {Spinner} from '@astryxdesign/core/Spinner';
import {VisuallyHidden} from '@astryxdesign/core/VisuallyHidden';
import {themeProps} from '@astryxdesign/core/utils';
import {focusOutlineProps} from '@astryxdesign/core/utils/focusOutline.stylex';
import {registerEnglishFallback} from '../i18n/englishFallback';
