  /** Whether the user has scrolled up past buttonThreshold. */
  isScrolledUp: boolean;

  /** Whether auto-scroll is locked (following content). */
  isLocked: boolean;

  /** Scroll to the bottom of the container and re-lock. */
  scrollToBottom: (options?: ChatScrollToBottomOptions) => void;

  /** Scroll so a specific element is at the top of the visible area. No lock change. */
  scrollToMessage: (el: HTMLElement) => void;

  /** Lock auto-scroll and scroll to bottom. */
  lock: () => void;

  /** Unlock auto-scroll. */
  unlock: () => void;

  /** Scroll to bottom if currently locked. Call on content resize. */
  scrollIfLocked: () => void;

  /** Scroll to the last message in the container. */
  scrollToLastMessage: () => void;
}

// =============================================================================
// Hook
// =============================================================================

const SIXTY_FPS_MS = 1000 / 60;

// The scrollers whose hook follows the newest message now, kept in step with
// each hook's lock.
const following = new WeakSet<Element>();

/**
 * Whether the stream scroll on `scroller` follows its newest message now, as
 * its lock says. Internal to Chat.
 */
export function isFollowingNewest(scroller: Element): boolean {
  return following.has(scroller);
}

// The lock's marks on the scroller: anchoring off while the hook follows, and
// the state `isFollowingNewest` reads.
function markFollowing(el: Element, locked: boolean): void {
  setScrollAnchoringOff(el, locked);
  if (locked) {
    following.add(el);
  } else {
    following.delete(el);
  }
}

// The page's scroll fires at the document. The root's box moves up by that
// scroll.
function scrollsPage(el: HTMLElement): boolean {
  const doc = el.ownerDocument;
  return el === doc.scrollingElement || el === doc.documentElement;
}

export function useChatStreamScroll({
  scrollRef,
  enabled = true,
  lockThreshold = 10,
  buttonThreshold = 100,
  damping = 0.7,
  stiffness = 0.05,
  mass = 1.25,
}: UseChatStreamScrollOptions): UseChatStreamScrollReturn {
  const [isScrolledUp, setIsScrolledUp] = useState(false);
  const [isLocked, setIsLocked] = useState(true);

  const lockedRef = useRef(true);
