  const invalidate = () => {
    boxes = null;
    targetBox = null;
  };
  const followPointer = (event: PointerEvent) => {
    if (event.pointerId === pointerId) {
      const {clientX: x, clientY: y} = event;
      if (isOverLayer(x, y)) {
        holdCapture(null);
