export function watchOutsidePress(
  owner: Element,
  isInside: (path: ReadonlyArray<EventTarget>) => boolean,
  onOutside: () => void,
  {pointerTypes, closesOnPan = false, root = null}: OutsidePressOptions = {},
): () => void {
