    if (!follows(event) || (closesOnPan && panStart?.id !== event.pointerId)) {
      return;
    }
    const wasOutside = startedOutside;
    startedOutside = false;
    panStart = null;
    if (wasOutside && !isInside(event.composedPath())) {
      noteOutsideDismissal(doc);
      onOutside();
    }
